from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and separate the groups of nested parentheses
    def is_balanced(s):
        stack = []
        result = []
        for i, char in enumerate(s):
            if char == '(':
                stack.append(i)
            elif char == ')':
                if stack:
                    start = stack.pop()
                    result.append(s[start:i+1])
        return result

    # Step 3: Check if the separated groups are balanced
    balanced_groups = is_balanced(paren_string)

    # Step 4: Return the list of balanced groups
    return balanced_groups

